  function mount(node,options){root=node;helpers=options;render();}
  function shell(body){
    root.innerHTML=`<section class="commerce-admin"><a class="back-link" href="#dashboard">← Back to dashboard</a><header class="ca-header"><div><p class="eyebrow">Workspace</p><h2>Website & Content</h2><p>Products, pages, media and publishing for the Flaxx website.</p></div><div class="ca-header-actions"><a class="ca-button" href="/?core-preview=1#home" target="_blank">Preview website</a>${button('Add product','data-ca-add-product','primary')}</div></header><nav class="ca-tabs" aria-label="Website and content sections">${[['overview','Overview'],['products','Products'],['collections','Collections'],['pages','Pages'],['homepage','Homepage'],['navigation','Navigation'],['media','Media'],['publishing','Publishing']].map(([value,label])=>`<button data-ca-tab="${value}" class="${tab===value?'active':''}">${label}</button>`).join('')}</nav><div id="ca-body">${body}</div><p class="ca-footer-note">${e(helpers.roleName)} · Draft changes are saved in this browser until the production content service is connected.</p></section>`;
  }
  function render(){if(!root)return;if(editing?.kind==='product'){shell(renderProductEditor(editing.id));return;}if(editing?.kind==='page'){shell(renderPageEditor(editing.id));return;}if(editing?.kind==='collection'){shell(renderCollectionEditor(editing.id));return;}if(editing?.kind==='hero'){shell(renderHeroEditor(editing.id));return;}shell(renderTab());}
  function renderTab(){if(tab==='products')return renderProducts();if(tab==='collections')return renderCollections();if(tab==='pages')return renderPages();if(tab==='homepage')return renderHomepage();if(tab==='navigation')return renderNavigation();if(tab==='media')return renderMedia();if(tab==='publishing')return renderPublishing();return renderOverview();}
  function renderOverview(){const pending=data.products.filter(p=>p.verification!=='Batch released').length;return `<section class="ca-stats"><article class="ca-stat"><strong>${data.products.length}</strong><span>Products</span></article><article class="ca-stat"><strong>${data.pages.length}</strong><span>Pages</span></article><article class="ca-stat"><strong>${data.collections.length}</strong><span>Collections</span></article><article class="ca-stat"><strong>${data.media.length}</strong><span>Media files</span></article></section><section class="ca-dashboard"><article class="ca-panel"><div class="ca-panel-head"><div><h3>Products</h3><p>Inventory, price and release status</p></div><button data-ca-tab="products">View all →</button></div>${data.products.map(productRowCompact).join('')}</article><article class="ca-panel"><div class="ca-panel-head"><div><h3>Needs attention</h3><p>Before customer release</p></div><span>${pending+2}</span></div><ul class="ca-notices"><li><strong>${pending} products await verification</strong>They can be edited and previewed, but cannot be published.</li><li><strong>Production publishing is not connected</strong>Current changes remain browser drafts.</li><li><strong>Fit and verification pages are drafts</strong>Finish their copy before launch.</li></ul></article><article class="ca-panel wide"><div class="ca-panel-head"><div><h3>Website structure</h3><p>Customer-facing pages and sections</p></div><button data-ca-tab="homepage">Manage homepage →</button></div>${data.pages.slice(0,5).map(pageRowCompact).join('')}</article></section>`;}
